            string connectionString = "DATA SOURCE=BMI;USER ID=FOXPRO;Password=pass";
            //duz olan
            string daily_report = "SELECT ar.date_oper AS tarix, ar.licsch AS hesab, " +
               "CASE WHEN SUBSTR(ar.licsch, 0, 3) IN ('159','209','219','239','259') THEN SUBSTR(ar.licsch, 16, 2) " +
               "ELSE SUBSTR(ar.licsch, 6, 2) END AS valyuta, " +
               "ar.saldo_ish_nacval AS qaliq " +
               "FROM odb.arh_saldo_ls ar, licsch ch " +
               "WHERE ar.date_oper = TO_DATE('" + textBox2.Text + "', 'dd/mm/yyyy') " +
               "AND ch.licsch = ar.licsch " +
               "AND (ch.date_close_licsch IS NULL OR ar.date_oper <= ch.date_close_licsch)";

            string daily_report_bk = "select t.date_oper tarix,t.vbs,t.licsch,substr(t.licsch,6,2),t.ssls,t.ostatok_ish," +
                "t.ostatok_ish*ROUND(odb.func_get_kurval(substr(t.licsch,6,2),t.date_oper),6) ekv," +
                "ROUND(odb.func_get_kurval(substr(t.licsch,6,2),t.date_oper),6)  kurs " +
                "from odb.arh_saldo_vbls t where t.date_oper =TO_DATE('" + textBox2.Text + "', 'dd/mm/yyyy') and t.vbs in (99530,99531,99550,99300,99301) and t.ostatok_ish<>0";

            string daily_report_kataloq = "select al.date_oper,al.licschkre,substr(al.licschkre,6,2), tk.code,tk.name,al.summa,al.summa_19," +
                "(al.summa+al.summa_19)*ROUND(odb.func_get_kurval(substr(al.licschkre,6,2),al.date_oper),6) ekv," +
                "ROUND(odb.func_get_kurval(substr(al.licschkre,6,2),al.date_oper),6) kurs " +
                    "from arh_licschkre al,tipkre tk where al.tipkredita = tk.code and (al.date_close is null or al.date_close>TO_DATE('" + textBox3.Text + "', 'dd/mm/yyyy')) " +
                    "and al.date_oper=TO_DATE('" + textBox2.Text + "', 'dd/mm/yyyy')";

            string daily_report1 = "SELECT ar.date_oper AS tarix, ar.licsch AS hesab, " +
               "CASE WHEN SUBSTR(ar.licsch, 0, 3) IN ('159','209','219','239','259') THEN SUBSTR(ar.licsch, 16, 2) " +
               "ELSE SUBSTR(ar.licsch, 6, 2) END AS valyuta, " +
               "ar.saldo_ish_nacval AS qaliq " +
               "FROM odb.arh_saldo_ls ar, licsch ch " +
               "WHERE ar.date_oper = TO_DATE('" + textBox3.Text + "', 'dd/mm/yyyy') " +
               "AND ch.licsch = ar.licsch " +
               "AND (ch.date_close_licsch IS NULL OR ar.date_oper <= ch.date_close_licsch)";

            string daily_report_bk1 = "select t.date_oper tarix,t.vbs,t.licsch,substr(t.licsch,6,2),t.ssls,t.ostatok_ish," +
                "t.ostatok_ish*ROUND(odb.func_get_kurval(substr(t.licsch,6,2),t.date_oper),6) ekv," +
                "ROUND(odb.func_get_kurval(substr(t.licsch,6,2),t.date_oper),6)  kurs " +
                "from odb.arh_saldo_vbls t where t.date_oper =TO_DATE('" + textBox3.Text + "', 'dd/mm/yyyy') and t.vbs in (99530,99531,99550,99300,99301) and t.ostatok_ish<>0";

            string daily_report_kataloq1 = "select al.date_oper,al.licschkre,substr(al.licschkre,6,2), tk.code,tk.name,al.summa,al.summa_19," +
                "(al.summa+al.summa_19)*ROUND(odb.func_get_kurval(substr(al.licschkre,6,2),al.date_oper),6) ekv," +
                "ROUND(odb.func_get_kurval(substr(al.licschkre,6,2),al.date_oper),6) kurs " +
                    "from arh_licschkre al,tipkre tk where al.tipkredita = tk.code and (al.date_close is null or al.date_close>TO_DATE('" + textBox3.Text + "', 'dd/mm/yyyy')) " +
                    "and al.date_oper=TO_DATE('" + textBox3.Text + "', 'dd/mm/yyyy')";

            string gun_erzinde_odenisler = "select case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end tar " +
",'odenisler'gun_erzinde,round(sum(d.summa_v_nacval) / 1000, 2) meb from arh_licschkre l, arh_dd d,odb.balschkli b " +
"where d.kredit in (l.licschkre, l.licsch_19) and d.date_oper between to_date('" + textBox3.Text + "', 'dd-mm-yyyy') and to_date('" + textBox2.Text + "','dd-mm-yyyy')  " +
"and l.date_oper = d.date_oper and substr(d.debet,1,5)= b.balsch and substr(d.debet,10,6)= substr(d.kredit, 10, 6) " +
"and d.ssk = l.subschkre group by case when d.date_oper = to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end ";
            string qaliqlar_30_90 = "SELECT case when m.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end tar," +
    " odb.tar_ferq360(x.date_oper, nvl(x.lastoverduedate, x.date_oper)) gec_gun," +
"((m.summa * ROUND(odb.func_get_kurval(substr(m.licschkre, 6, 2), m.date_oper), 6)) + (m.summa_19 * ROUND(odb.func_get_kurval(substr(m.licschkre, 6, 2), m.date_oper), 6))) / 1000 qal " +
 "            from view_nacpogprokre_all x, arh_licschkre m where" +
" x.date_oper = m.date_oper " +
 "  and x.licschpkre = m.licschpkre and x.subschkre = m.subschkre " +
  " and m.date_oper between to_date('" + textBox3.Text + "', 'dd-mm-yyyy') and to_date('" + textBox2.Text + "','dd-mm-yyyy') and m.date_close is null  " +
  " and x.licschpkre = m.licschpkre and x.subschkre = m.subschkre " +
  " and m.date_close is null ";
            string qaliqlar_kr_tip = "select case when m.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end tar," +
                "m.tipkredita tip, " +
    "sum((m.summa * ROUND(odb.func_get_kurval(substr(m.licschkre, 6, 2), m.date_oper), 6)) + (m.summa_19 * ROUND(odb.func_get_kurval(substr(m.licschkre, 6, 2), m.date_oper), 6))) / 1000 qal " +
     "            from arh_licschkre m " +
   "where m.date_oper between to_date('" + textBox3.Text + "', 'dd-mm-yyyy') and to_date('" + textBox2.Text + "','dd-mm-yyyy') and m.date_close is null " +
   "group by case when m.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end," +
   "m.tipkredita";

            string medaxiller = "select case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end tar," +
                "CASE    " +
    "WHEN r.yurik = 1 then 'huquqi' " +
    "WHEN r.yurik = 0  THEN 'fiziki' " +
    "ELSE 'unknown' END AS tip,round(sum(d.summa_v_nacval) / 1000, 2) meb " +
    "      from arh_dd d, regnom r,odb.balschkli b,licsch l " +
  " where d.date_oper between to_date('" + textBox3.Text + "', 'dd-mm-yyyy') and to_date('" + textBox2.Text + "','dd-mm-yyyy') and substr(d.kredit,1,5)= b.balsch " +
  "and d.kredit=l.licsch and l.registrac_nomer=r.regnom " +
  "and substr(d.debet,1,5) not in ('66220', '86220') " +
  " group by case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end," +
  "CASE " +
  "  WHEN r.yurik = 1 then 'huquqi' " +
  "  WHEN r.yurik = 0  THEN 'fiziki' " +
  "  ELSE 'unknown' END";
            string mexaricler = "select case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end tar," +
                "CASE  " +
   " WHEN r.yurik = 1 then 'huquqi' " +
   " WHEN r.yurik = 0  THEN 'fiziki' " +
   " ELSE 'unknown' END AS tip,round(sum(d.summa_v_nacval) / 1000, 2) meb " +
   " from arh_dd d, regnom r,odb.balschkli b,licsch l " +
   " where d.date_oper between to_date('" + textBox3.Text + "', 'dd-mm-yyyy') and to_date('" + textBox2.Text + "','dd-mm-yyyy') and substr(d.debet,1,5)= b.balsch " +
   " and d.debet = l.licsch and l.registrac_nomer = r.regnom" +
   " and substr(d.kredit,1,5) not in ('66220', '86220') " +
   " group by case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end ," +
   " CASE" +
   " WHEN r.yurik = 1 then 'huquqi'" +
   " WHEN r.yurik = 0  THEN 'fiziki'" +
   " ELSE 'unknown' END";
            string ver_kr_lar = "select case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end tar," +
   " CASE" +
   " WHEN r.yurik = 1 then 'huquqi'" +
   " WHEN r.yurik = 0  THEN 'fiziki'" +
   " ELSE 'unknown' END AS tip" +
   " ,sum(d.summa_v_nacval) / 1000 from arh_dd d,regnom r, arh_licschkre l,odb.balschkli b" +
   "  where d.date_oper between to_date('" + textBox3.Text + "', 'dd-mm-yyyy') and to_date('" + textBox2.Text + "','dd-mm-yyyy') and d.debet = l.licschkre" +
   " and substr(d.kredit,10,6)= substr(l.licschkre, 10, 6)" +
   "  and l.date_oper = d.date_oper and substr(d.kredit,1,5)= b.balsch and d.ssd = l.subschkre and l.date_close is null " +
   "and substr(d.debet,10,6)= r.regnom" +
   "  group by case when d.date_oper=to_date('" + textBox3.Text + "','dd/mm/yyyy') then 'dunen' else 'bugun' end," +
   "CASE" +
   " WHEN r.yurik = 1 then 'huquqi'" +
    "WHEN r.yurik = 0  THEN 'fiziki'" +
   " ELSE 'unknown' END";

